import{_ as e,c as t,o as a,V as i}from"./chunks/framework.B6I5AJO8.js";const m=JSON.parse('{"title":"Introduction","description":"","frontmatter":{"sidebarDepth":3},"headers":[],"relativePath":"about/introduction.md","filePath":"about/introduction.md"}'),o={name:"about/introduction.md"},r=i('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p><strong>knowledge</strong> is an AI developer assistant for the Kalisio ecosystem. It indexes the entire codebase into a vector database and serves it to coding agents through a retrieval API, so that agents retrieve only the chunks relevant to a task instead of reading whole files.</p><h2 id="the-problem" tabindex="-1">The problem <a class="header-anchor" href="#the-problem" aria-label="Permalink to &quot;The problem&quot;">​</a></h2><h2 id="what-knowledge-provides" tabindex="-1">What knowledge provides <a class="header-anchor" href="#what-knowledge-provides" aria-label="Permalink to &quot;What knowledge provides&quot;">​</a></h2><ul><li><strong>Semantic code search</strong> — retrieval over an indexed vector database. See <a href="/knowledge/architecture/rag.html">RAG: indexing &amp; retrieval</a>.</li><li><strong>Structure-aware ingestion</strong> — per–file-type chunking (Markdown, JS, Vue, JSON), with incremental re-indexing of only what changed. See <a href="/knowledge/architecture/ingestion-pipeline.html">Ingestion pipeline</a>.</li><li><strong>Commit-history enrichment</strong> — each chunk carries its file&#39;s recent commit history, so answers reflect how a file changed. See <a href="/knowledge/architecture/ingestion-pipeline.html">Ingestion pipeline</a>.</li><li><strong>Retrieval API</strong> — <code>/ask</code> (RAG answer) and <code>/search</code> (chunks), JWT-secured. See <a href="/knowledge/architecture/api.html">API endpoints</a>.</li></ul><h2 id="how-it-fits-the-kalisio-ecosystem" tabindex="-1">How it fits the Kalisio ecosystem <a class="header-anchor" href="#how-it-fits-the-kalisio-ecosystem" aria-label="Permalink to &quot;How it fits the Kalisio ecosystem&quot;">​</a></h2><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li>Curious about the internals? Start with the <a href="/knowledge/architecture/introduction.html">Architecture overview</a>.</li><li>Want the research behind the design? See <a href="/knowledge/research/introduction.html">Research</a>.</li></ul>',8),n=[r];function s(h,l,c,d,u,p){return a(),t("div",null,n)}const f=e(o,[["render",s]]);export{m as __pageData,f as default};
